// This shader tries to replicate the effect in the youtube video
// https://www.youtube.com/watch?v=1zu41rrc_Ng&t=331s
// But the outcome is different.
//
// I guess the video only shows stable orbits.
// If you have any advice, please leave it in the comment :)
//
// The settings are in the *Common* tab.

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = texture(iChannel0, fragCoord / iResolution.xy);
#if ROTATE
    vec2 pos_jup = vec2(R, 0);
#else
    float theta = 2. * 3.14159 / T * float(iFrame) * SIM_dt;
    vec2 pos_jup = R * vec2(cos(theta), sin(theta));
#endif
    vec2 p = (fragCoord * 2. - iResolution.xy) / iResolution.x;
    fragColor+=vec4(
        smoothstep(.04,0.,length(p))+
        smoothstep(.02,0.,length(p - pos_jup * SIM_scale))
    )*1.5;
}

// Calculate comet position

vec2 gravity(vec2 r) {
    return -G * r * pow(length(r), -3.);
}

void mainImage(out vec4 pos, in vec2 fragCoord) {
    ivec2 index = ivec2(fragCoord);
    if (index.x > W_comet || index.y > H_comet) {
        return;
    }
    if (iFrame == 0) {
        pos = vec4(0);
        return;
    }
    float theta = 2. * 3.14159 / T * float(iFrame) * SIM_dt;
    vec2 pos_jup = R * vec2(cos(theta), sin(theta));
    pos = texelFetch(iChannel0, index, 0);
    float r1 = length(pos.xy);
    float r2 = length(pos.xy - pos_jup);
    if (r1 < ABSORB_MIN || r1 > ABSORB_MAX || r2 < ABSORB_MIN) {
        pos = sin(1234.567 * (fract(iTime) + texelFetch(iChannel1, index, 0)));
        pos.xy = pos.xy / SIM_scale;
        pos.zw = pos.xy + pos.zw * 1e10;
    }
    pos = vec4(
        pos.xy * 2. - pos.zw +
            (M_sun * gravity(pos.xy) +
             M_jup * gravity(pos.xy - pos_jup)) *
                SIM_dt * SIM_dt,
        pos.xy);
}

// Astronomical Constants
#define M_sun 1.98892e30
#define M_jup 1.8987e27
#define R     7.78e11
#define G     6.6743e-11
#define T     3.74e8

// time interval
#define SIM_dt    8e5
// canvas scaling
#define SIM_scale 5e-13
// number of comets = W_comet * H_comet
#define W_comet  32
#define H_comet  64
// display radius of a comet
#define R_comet  0.002
// absorb the comet if it is too close to the star
#define ABSORB_MIN 3e10
// or if it is outside of the scene
#define ABSORB_MAX 5e12
// whether to rotate the reference frame
#define ROTATE 0

// Render trajectory

// https://iquilezles.org/articles/distfunctions2d/
float sdSegment(in vec2 p, in vec2 a, in vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame == 0) {
        fragColor = vec4(0);
        return;
    }
    float col = 0.;
    vec2 p = (fragCoord * 2. - iResolution.xy) / iResolution.x;
#if ROTATE
    float theta = 2. * 3.14159 / T * float(iFrame) * SIM_dt;
    p = mat2(cos(theta), sin(theta), -sin(theta), cos(theta)) * p;
#endif
    for (int i = 0; i < W_comet; ++i) {
        for (int j = 0; j < W_comet; ++j) {
            vec4 q = texelFetch(iChannel0, ivec2(i, j), 0) * SIM_scale;
            if (sdSegment(p, q.xy, q.zw) < R_comet && length(p - q.zw) > R_comet) {
                col = 1.;
                break;
            }
        }
        if (col > .5) {
            break;
        }
    }
    fragColor = texture(iChannel1, fragCoord / iResolution.xy) * .99 + .7 * vec4(col * vec3(.8, .5, .2), 1.);
}
